<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { ArrowRight, ChartNoAxesCombined, Clock3, Database, MapPin } from 'lucide-vue-next'
import { useRoute } from 'vue-router'
import MetricComparison from '../components/charts/MetricComparison.vue'
import ProbabilityRing from '../components/charts/ProbabilityRing.vue'
import SportIdentity from '../components/identity/SportIdentity.vue'
import SportCrumbs from '../components/navigation/SportCrumbs.vue'
import LoadingState from '../components/ui/LoadingState.vue'
import LoadError from '../components/ui/LoadError.vue'
import { entityRoute, gamePrediction, metricValue, probability, sentenceCase, sportLabel } from '../domain/sports'
import { sportById } from '../config/sports'
import { api } from '../services/api'
const props=defineProps({sport:{type:String,required:true}}),route=useRoute(),payload=ref(null),loading=ref(true),error=ref('')
const active=computed(()=>sportById(props.sport)),game=computed(()=>payload.value?.identity||{}),pick=computed(()=>gamePrediction(game.value))
const predictionRows=computed(()=>Object.entries(game.value?.prediction?.markets||{}).filter(([,value])=>Number.isFinite(Number(value))).map(([key,value])=>{const prediction=game.value.prediction;const priceKey={home_win:'home_moneyline',away_win:'away_moneyline'}[key]||key;return{key,label:sentenceCase(key),value:Number(value),fair:Number(prediction.fair_odds?.[priceKey]??prediction.fair_odds?.[key])||null,market:Number(prediction.prices?.[priceKey]??prediction.prices?.[key])||null,noVig:Number(prediction.no_vig_market_probability?.[priceKey]??prediction.no_vig_market_probability?.[key])||null,edge:Number.isFinite(Number(prediction.edge?.[priceKey]??prediction.edge?.[key]))?Number(prediction.edge?.[priceKey]??prediction.edge?.[key]):null}}).sort((a,b)=>b.value-a.value))
const comparison=computed(()=>{const p=game.value?.prediction; if(p?.expected_goals)return[{label:'Expected goals',left:Math.min(100,p.expected_goals.away/3*100),right:Math.min(100,p.expected_goals.home/3*100),leftDisplay:metricValue(p.expected_goals.away,2),rightDisplay:metricValue(p.expected_goals.home,2)},{label:'Win probability',left:Number(p.markets.away_win)*100,right:Number(p.markets.home_win)*100,leftDisplay:probability(p.markets.away_win),rightDisplay:probability(p.markets.home_win)}];if(p?.expected_score)return[{label:'Expected points',left:Math.min(100,p.expected_score.away/40*100),right:Math.min(100,p.expected_score.home/40*100),leftDisplay:metricValue(p.expected_score.away,1),rightDisplay:metricValue(p.expected_score.home,1)},{label:'Win probability',left:Number(p.markets.away_win)*100,right:Number(p.markets.home_win)*100,leftDisplay:probability(p.markets.away_win),rightDisplay:probability(p.markets.home_win)}];return[]})
const load=async()=>{loading.value=true;error.value='';try{payload.value=await api.sportWorkspace(props.sport,'game',route.params.id,{competition:route.query.competition,discipline:route.query.discipline,tournament:route.query.tournament})}catch(caught){error.value=caught?.message||'The match workspace could not be loaded.'}finally{loading.value=false}}
watch(()=>[props.sport,route.params.id],load);onMounted(load)
</script>
<template><div class="match-view" :style="{'--sport':active.accent}"><LoadingState v-if="loading" label="Opening match intelligence" detail="Resolving the fixture, participants and available prediction evidence."/><LoadError v-else-if="error" :message="error" @retry="load"/><template v-else>
  <SportCrumbs :items="[{label:sportLabel(sport),to:active.route},{label:payload.league?.name||game.competition,to:payload.league?entityRoute(sport,'leagues',payload.league):`${active.route}/leagues`},{label:`${game.away?.name} vs ${game.home?.name}`}]"/>
  <section class="match-hero"><div class="teams"><RouterLink :to="entityRoute(sport,'teams',game.away,{competition:game.competitionId,discipline:game.competitionId})"><SportIdentity :identity="game.away" :size="100" square/><span>AWAY</span><h1>{{game.away?.name}}</h1><b v-if="game.away?.score!=null">{{game.away.score}}</b></RouterLink><div class="event"><span>{{game.status}}</span><strong>VS</strong><p><Clock3/> {{game.date}} · {{game.time}}</p><p><MapPin/> {{game.venue}}</p></div><RouterLink :to="entityRoute(sport,'teams',game.home,{competition:game.competitionId,discipline:game.competitionId})"><SportIdentity :identity="game.home" :size="100" square/><span>HOME</span><h1>{{game.home?.name}}</h1><b v-if="game.home?.score!=null">{{game.home.score}}</b></RouterLink></div><aside><template v-if="pick"><ProbabilityRing :value="pick.probability" :label="pick.label" :detail="game.prediction?.modelStatus||game.prediction?.status" :size="210"/><RouterLink :to="{path:`/${sport}/builder`,query:{competition:game.competitionId,discipline:game.competitionId}}">OPEN BUILDER <ArrowRight/></RouterLink></template><template v-else><Database/><b>No attached forecast</b><p>This match is source-backed, but its current event ID is not in the prediction export.</p></template></aside></section>
  <section v-if="predictionRows.length" class="markets"><header><div><span class="eyebrow">MODEL DISTRIBUTION</span><h2>Every supported outcome</h2></div><ChartNoAxesCombined/></header><div><article v-for="row in predictionRows" :key="row.key"><small>{{row.label}}</small><b>{{probability(row.value)}}</b><dl><span>FAIR {{row.fair?row.fair.toFixed(3):'—'}}</span><span>MARKET {{row.market?row.market.toFixed(3):'—'}}</span><span>{{row.edge==null?'NO EDGE DATA':`EDGE ${row.edge>=0?'+':''}${probability(row.edge)}`}}</span></dl><i><span :style="{width:`${row.value*100}%`}"></span></i></article></div></section>
  <section class="analysis"><article><header><span class="eyebrow">PARTICIPANT COMPARISON</span><h2>{{comparison.length?'What separates the sides':'Verified match identity'}}</h2></header><MetricComparison v-if="comparison.length" :rows="comparison" :left-label="game.away?.shortName||game.away?.name" :right-label="game.home?.shortName||game.home?.name"/><div v-else class="empty">No score-distribution metrics are attached to this match.</div></article><article><header><span class="eyebrow">MODEL CONTEXT</span><h2>Interpretation</h2></header><p v-if="game.prediction?.expected_goals">NINTH expects {{metricValue(game.prediction.expected_goals.total,2)}} total goals. The three most likely scorelines are {{game.prediction.likely_scores?.map(row=>`${row.score} (${probability(row.probability)})`).join(', ')||'not exported'}}.</p><p v-else-if="game.prediction?.expected_score">The joint score distribution expects {{metricValue(game.prediction.expected_score.total,1)}} total points and a {{metricValue(Math.abs(game.prediction.expected_score.home_margin),1)}}-point home-margin magnitude.</p><p v-else-if="pick">The current model favors {{pick.label}} at {{probability(pick.probability)}}. Builder eligibility remains a separate evidence check.</p><p v-else>There is no safe analytical narrative because the current prediction export does not include this event.</p><small>Source · {{game.source||'connected sport provider'}}</small></article></section>
</template></div></template>
<style scoped>.match-view{padding:18px 0 70px}.match-hero{min-height:510px;display:grid;grid-template-columns:1fr 310px;gap:35px;align-items:center;border-bottom:1px solid var(--line)}.teams{display:grid;grid-template-columns:1fr 150px 1fr;align-items:center;gap:20px}.teams>a{min-width:0;display:grid;justify-items:center;text-align:center;color:var(--text);text-decoration:none}.teams>a span{margin-top:14px;font:800 7px 'DM Mono';color:var(--sport)}.teams h1{margin:8px 0 0;font-size:clamp(28px,4vw,56px);line-height:.94;letter-spacing:-.065em;overflow-wrap:anywhere}.teams>a>b{font:800 43px 'DM Mono';color:var(--sport)}.event{text-align:center}.event>span{font:800 7px 'DM Mono';color:var(--sport)}.event>strong{display:block;margin:12px 0;font:800 26px 'DM Mono'}.event p{display:flex;align-items:center;justify-content:center;gap:5px;margin:6px 0;color:var(--muted);font-size:8px}.event svg{width:12px}.match-hero aside{min-height:310px;padding:20px;display:grid;place-items:center;align-content:center;background:var(--contrast);color:var(--on-contrast);border-top:4px solid var(--sport);text-align:center}.match-hero aside>a{display:flex;align-items:center;gap:7px;color:var(--on-contrast);font:700 8px 'DM Mono';text-decoration:none}.match-hero aside>a svg{width:14px;color:var(--sport)}.match-hero aside>svg{color:var(--sport)}.match-hero aside>b{margin-top:15px}.match-hero aside>p{color:#939b90;font-size:9px}.markets{margin-top:30px;border:1px solid var(--line);background:var(--surface)}.markets>header{min-height:90px;padding:18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}h2{margin:5px 0 0;font-size:29px;letter-spacing:-.05em}.markets>header svg{color:var(--sport)}.markets>div{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1px;background:var(--line)}.markets article{min-height:155px;padding:15px;display:flex;flex-direction:column;background:var(--surface)}.markets small{font:700 7px 'DM Mono';color:var(--muted)}.markets b{margin:auto 0 9px;font:800 25px 'DM Mono'}.markets dl{display:flex;flex-wrap:wrap;gap:5px;margin:0 0 10px}.markets dl span{padding:4px 5px;border:1px solid var(--line);font:700 6px 'DM Mono';color:var(--muted)}.markets i{height:5px;background:var(--line)}.markets i span{display:block;height:100%;background:var(--sport);transition:width .6s}.analysis{display:grid;grid-template-columns:1fr .72fr;gap:12px;margin-top:12px}.analysis>article{padding:20px;border:1px solid var(--line);background:var(--surface)}.analysis article>header{margin-bottom:22px}.analysis article>p{font-size:13px;line-height:1.75}.analysis article>small{font:600 7px 'DM Mono';color:var(--muted)}.empty{min-height:180px;display:grid;place-items:center;color:var(--muted);font-size:9px}@media(max-width:1020px){.match-hero{grid-template-columns:1fr;padding:40px 0}.match-hero aside{min-height:260px}.analysis{grid-template-columns:1fr}}@media(max-width:650px){.teams{grid-template-columns:1fr 45px 1fr;gap:6px}.teams h1{font-size:23px}.event p{display:none}.event>strong{font-size:16px}.teams :deep(.sport-identity){width:64px!important;height:64px!important}.match-hero aside{min-height:240px}}</style>
